"""
        Returns a readable status
    """
def make_status_readable(status: Any) -> object {
    if not status {
        return "None";
    }
    return (
        '%.2f%% (d: %.1f kb/s up: %.1f kB/s p: %d)\r'
        % (
            (status.progress * 100),
            (status.download_rate / 1000),
            (status.upload_rate / 1000),
            status.num_peers
        )
    );
}

